def capability_catalog(service, workspace_id=None):
    restricted = {'P02', 'S07', 'S09', 'W03', 'C01', 'C02', 'C03', 'C04', 'C05', 'M01'}
    return [{'capability_id': cid, 'description': description, 'cli': cli, 'mcp': mcp,
             'scope': 'application' if cid in {'S08', 'V01', 'W03', 'M01'} else 'workspace',
             'effects': ['read'] if cid not in {'P03','P04','A01','A03'} else ['read', 'network'],
             'required_permissions': ['allow_llm', 'allowed_llm_origin', 'allowed_credential_ref']
                 if cid in {'P03','P04','A01','A03'} else [],
             'availability': 'pending',
             'restriction': 'Local administration/UI required for restricted mutations; MCP maintenance is read-only'
                 if cid in restricted else '', 'slice': number}
            for cid, description, cli, mcp, number in INVENTORY]
